function useRoute() {
  const read = () => { const value = window.location.hash.replace(/^#/, ""); return value?.startsWith("/") ? value : "/"; };
  const [route,setRoute] = useState(read);
  useEffect(() => { const onChange=()=>{setRoute(read());window.scrollTo({top:0,left:0,behavior:"instant"});}; window.addEventListener("hashchange",onChange); return()=>window.removeEventListener("hashchange",onChange); },[]);
  return route;
}

function RouteLink({to,className="",children,...props}) { return <a href={`#${to}`} className={className} {...props}>{children}</a>; }

function Brand({inverse=false,compact=false}) {
  return <span className={`brand ${inverse?"brand-inverse":""} ${compact?"brand-compact":""}`}><span className="brand-mark"><img src={`${ASSETS}/jet-dencre-monogram-light.png`} alt="" /></span>{!compact&&<span className="brand-copy"><strong>Jet d’Encre</strong><small>ÉDITIONS</small></span>}</span>;
}

function scrollToId(id) { document.getElementById(id)?.scrollIntoView({behavior:"smooth",block:"start"}); }

